// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DA VTEX (OMS, ITEMS, CLIENT PROFILE, PAYMENT)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

const client = body.clientProfileData || {};
let rawPhone = (client.phone || body.shippingData?.address?.receiverName || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = `${client.firstName || 'Cliente'} ${client.lastName || ''}`.trim();
const clienteEmail = (client.email || '').trim().toLowerCase();
const clienteDoc = (client.document || '').toString().replace(/\D/g, '');

const orderId = body.orderId || body.id || Date.now().toString();
const numeroPedido = parseInt(orderId.replace(/\D/g, '') || Date.now(), 10);
const valorTotal = parseFloat(body.value || 0) / 100.0;
const status = (body.status || '').toLowerCase();

let statusOperacional = 'Pendente';
if (['payment-approved', 'invoiced', 'ready-for-handling'].includes(status)) {
  statusOperacional = 'Pago';
} else if (['canceled'].includes(status)) {
  statusOperacional = 'Cancelado';
}

const items = (body.items || []).map(i => ({
  produto_nome: i.name || 'Produto VTEX',
  sku: i.id || i.refId || 'SKU_VTEX',
  quantidade: parseInt(i.quantity || 1, 10),
  preco_venda: parseFloat(i.price || 0) / 100.0
}));

const dedupHash = crypto.createHash('sha256').update(`vtex_${numeroPedido}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    order_id_vtex: orderId,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    cliente_doc: clienteDoc,
    valor_total: valorTotal,
    status_operacional: statusOperacional,
    items: items
  }
}];
